/**
 * app_icon.hpp
 * Author: Miguel Mochizuki Silva
 * Description: The window icon, embedded in the binary as raw RGBA pixels
 */
#ifndef APP_ICON_HPP
#define APP_ICON_HPP

#include <SDL3/SDL.h>

// Width and height of the icon in pixels
const int ICON_SIZE = 128;

// Row-major R, G, B, A bytes, generated by tools/make_icon.py
extern const unsigned char ICON_RGBA[ICON_SIZE * ICON_SIZE * 4];

/**
 * Builds an SDL surface holding a copy of the icon
 *
 * Returns SDL_Surface*: The surface, to be freed with SDL_DestroySurface, or nullptr on failure
 */
SDL_Surface* makeIconSurface();

#endif
